import React, { useEffect, useState } from "react";
import { useParams, Link } from "react-router-dom";
import { Line } from "react-chartjs-2";
import "../static/css/detailsCrypto.css";
import "./ChartConfig";

const CryptoDetails = () => {
    const { id } = useParams();
    const [crypto, setCrypto] = useState(null);
    const [loading, setLoading] = useState(true);
    const [priceHistory, setPriceHistory] = useState([]);
    const [error, setError] = useState(null);

    console.log("redirect successful");
    console.log("ID de la crypto:", id);

    useEffect(() => {
        const username = "momo";
        const password = "Avignon2024@?";
        const credentials = btoa(`${username}:${password}`);

        fetch(`/api/cryptocurrencies/${id}`, {
            headers: {
                Authorization: `Basic ${credentials}`,
            },
        })
            .then((response) => {
                if (!response.ok) {
                    throw new Error(`Erreur HTTP : ${response.statusText}`);
                }
                return response.json();
            })
            .then((data) => {
                console.log("Données récupérées de l'API : ", data);
                setCrypto(data);
                setLoading(false);

                return fetch(`/api/cryptocurrencies/${data.name}/price-history`, {
                    headers: {
                        Authorization: `Basic ${credentials}`,
                    },
                });
            })
            .then((response) => {
                if (!response.ok) {
                    throw new Error(`Erreur HTTP : ${response.statusText}`);
                }
                return response.json();
            })
            .then((historyData) => {
                setPriceHistory(historyData);
            })
            .catch((error) => {
                console.error("Erreur lors de la récupération des données : ", error);
                setError(error.message);
                setLoading(false);
            });
    }, [id]);

    if (loading) {
        return <div>Chargement des données...</div>;
    }

    if (error) {
        return <div>Erreur : {error}</div>;
    }

    if (!crypto) {
        return <div>Aucune donnée trouvée pour cette cryptomonnaie.</div>;
    }

    const chartData = {
        labels: priceHistory.map((entry) => new Date(entry.timestamp).toLocaleString()),
        datasets: [
            {
                label: "Prix ($)",
                data: priceHistory.map((entry) => entry.price),
                fill: false,
                backgroundColor: "rgba(75,192,192,0.4)",
                borderColor: "rgba(75,192,192,1)",
            },
        ],
    };

    const options = {
        responsive: true,
        plugins: {
            legend: {
                position: "top",
            },
        },
    }

    return (
        <div className="crypto-details">
            <header className="header">
                <h1>La cryptomonnaie de l'avenir</h1>
                <div className="button-container">
                    <Link to="/Register">
                        <button className="inscription-details">Inscription</button>
                    </Link>

                    <Link to="/Login">
                        <button className="connexion-details">Connexion</button>
                    </Link>
                </div>
            </header>
            <Link to="/">Retour à la liste</Link>
            <h1>Détails de {crypto.name}</h1>
            <ul>
                <li><strong>Nom:</strong> {crypto.name}</li>
                <li><strong>Symbole:</strong> {crypto.symbol}</li>
                <li><strong>Rang:</strong> {crypto.rank}</li>
                <li><strong>Prix ($):</strong> {crypto.price ? crypto.price.toFixed(2) : 'N/A'}</li>
                <li><strong>Volume d'échange ($):</strong> {crypto.volume ? crypto.volume.toFixed(2) : 'N/A'}</li>
                <li><strong>Market Cap ($):</strong> {crypto.market ? crypto.market.toFixed(2) : 'N/A'}</li>
                <li><strong>Pourcentage de changement en
                    24h:</strong> {crypto.change ? crypto.change.toFixed(2) : 'N/A'}</li>
                <li><strong>VWAP en 24H:</strong> {crypto.vwap ? crypto.vwap.toFixed(2) : 'N/A'}</li>
                <li><strong>Timestamp:</strong> {crypto.timestamp ? new Date(crypto.timestamp).toLocaleString() : 'N/A'}
                </li>
            </ul>
            <div className="chart-container">
                <h2>Historique des prix</h2>
                <Line data={chartData} options={options} />
            </div>
        </div>
    );
}

export default CryptoDetails;
